import{_ as t,o,c as a,a2 as n}from"./chunks/framework.D7WGirly.js";const p=JSON.parse('{"title":"Documents — How-tos & Workflows","description":"","frontmatter":{},"headers":[],"relativePath":"documents-02-how-tos-and-workflows.md","filePath":"documents-02-how-tos-and-workflows.md"}'),i={name:"documents-02-how-tos-and-workflows.md"};function r(s,e,l,u,d,c){return o(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="documents-—-how-tos-workflows" tabindex="-1">Documents — How-tos &amp; Workflows <a class="header-anchor" href="#documents-—-how-tos-workflows" aria-label="Permalink to &quot;Documents — How-tos &amp; Workflows&quot;">​</a></h1><p><em>Step-by-step guides for the most common Document workflows</em></p><hr><h2 id="generating-a-document-with-ai" tabindex="-1">Generating a Document with AI <a class="header-anchor" href="#generating-a-document-with-ai" aria-label="Permalink to &quot;Generating a Document with AI&quot;">​</a></h2><p>AI generation is the fastest way to produce a Document. Lodestone uses the Feature Name, Feature Description, and your Organization Description from Settings to produce a structured first draft.</p><ol><li>Open the Feature Detail page by clicking a Feature name in the backlog.</li><li>Navigate to the Documents section.</li><li>Select the document type you want to generate (e.g. Opportunity Canvas, PRD, User Stories).</li><li>Click Generate.</li><li>Review the output — all content is fully editable from this point forward.</li></ol><blockquote><p><strong>Tip:</strong> The richness of your Feature Description has a direct impact on output quality. A one-sentence description produces a generic draft. A well-written paragraph that explains the problem, the user, and the intended outcome produces a significantly more useful starting point.</p></blockquote><hr><h2 id="writing-a-document-manually" tabindex="-1">Writing a Document Manually <a class="header-anchor" href="#writing-a-document-manually" aria-label="Permalink to &quot;Writing a Document Manually&quot;">​</a></h2><p>If you prefer to write from scratch rather than generate with AI, you can do that too.</p><ol><li>Open the Feature Detail page.</li><li>Navigate to the Documents section.</li><li>Select the document type.</li><li>Choose the option to write manually (rather than generate).</li><li>Write directly into the document editor.</li></ol><p>Manual and AI-generated documents are identical once created — both are fully editable going forward.</p><hr><h2 id="editing-a-document" tabindex="-1">Editing a Document <a class="header-anchor" href="#editing-a-document" aria-label="Permalink to &quot;Editing a Document&quot;">​</a></h2><p>All Documents are editable at any time, regardless of how they were created.</p><ol><li>Open the Feature Detail page.</li><li>Find the Document you want to edit in the Documents section.</li><li>Click into the document to open the rich text editor.</li><li>Use the formatting toolbar to apply bold, italic, headings, lists, and other formatting.</li><li>Edit content directly in the editor.</li></ol><p>There is no publish or approval step — edits are saved as you work.</p><blockquote><p><strong>Important:</strong> Don&#39;t navigate away while a Document is still generating. Lodestone saves the Document as soon as generation completes, but if you leave the page mid-generation, you&#39;ll return to a blank document as if the generation never happened. Wait for generation to finish before navigating elsewhere.</p></blockquote><hr><h2 id="regenerating-a-document" tabindex="-1">Regenerating a Document <a class="header-anchor" href="#regenerating-a-document" aria-label="Permalink to &quot;Regenerating a Document&quot;">​</a></h2><p>If you&#39;ve updated a Feature Description and want to refresh a Document&#39;s content, you can regenerate it.</p><blockquote><p><strong>Warning:</strong> Regenerating a Document immediately overwrites the existing content with no warning prompt and no way to recover the previous version. If you&#39;ve made edits you want to keep, copy them elsewhere before regenerating.</p></blockquote><hr><h2 id="exporting-a-document" tabindex="-1">Exporting a Document <a class="header-anchor" href="#exporting-a-document" aria-label="Permalink to &quot;Exporting a Document&quot;">​</a></h2><p>Each Document has an <strong>Export</strong> button with three format options: PDF, Markdown, and HTML. Use whichever format fits your destination.</p><h3 id="pdf" tabindex="-1">PDF <a class="header-anchor" href="#pdf" aria-label="Permalink to &quot;PDF&quot;">​</a></h3><ol><li>Open the Feature Detail page.</li><li>Find the Document you want to export.</li><li>Click the <strong>Export</strong> button and select <strong>PDF</strong>.</li><li>The PDF downloads immediately, ready to share.</li></ol><h3 id="markdown" tabindex="-1">Markdown <a class="header-anchor" href="#markdown" aria-label="Permalink to &quot;Markdown&quot;">​</a></h3><ol><li>Open the Feature Detail page.</li><li>Find the Document you want to export.</li><li>Click the <strong>Export</strong> button and select <strong>Markdown</strong>.</li><li>A <code>.md</code> file downloads, containing the document content in Markdown format.</li></ol><p>Markdown exports are useful for pasting into Notion, Confluence, GitHub, or any other Markdown-friendly tool.</p><h3 id="html-shareable-link" tabindex="-1">HTML (shareable link) <a class="header-anchor" href="#html-shareable-link" aria-label="Permalink to &quot;HTML (shareable link)&quot;">​</a></h3><ol><li>Open the Feature Detail page.</li><li>Find the Document you want to export.</li><li>Click the <strong>Export</strong> button and select <strong>HTML</strong>.</li><li>Lodestone generates a responsive HTML snapshot and returns a shareable <code>/share/...</code> link.</li><li>Copy the link and share it with anyone — the recipient can view the document in a browser without logging in to Lodestone.</li></ol><p>Unlike PDF and Markdown, the HTML export does not download a file — it produces a URL. Each time you click HTML export, a new snapshot is generated and a new URL is returned. Previous links remain valid.</p><hr><h2 id="exporting-an-opportunity-canvas-as-powerpoint" tabindex="-1">Exporting an Opportunity Canvas as PowerPoint <a class="header-anchor" href="#exporting-an-opportunity-canvas-as-powerpoint" aria-label="Permalink to &quot;Exporting an Opportunity Canvas as PowerPoint&quot;">​</a></h2><p>The Opportunity Canvas has an additional export option beyond PDF.</p><ol><li>Open the Feature Detail page.</li><li>Find the Opportunity Canvas.</li><li>Click the Export option and select PPT (or PowerPoint).</li><li>The slide downloads as a single .pptx file.</li></ol><p>This is especially useful when you want to include the canvas in a presentation without rebuilding it manually.</p><hr><h2 id="using-documents-across-different-audiences" tabindex="-1">Using Documents Across Different Audiences <a class="header-anchor" href="#using-documents-across-different-audiences" aria-label="Permalink to &quot;Using Documents Across Different Audiences&quot;">​</a></h2><p>Different document types are suited to different audiences. A few common patterns:</p><ul><li><strong>Aligning leadership or stakeholders</strong> → Opportunity Canvas (exported as PDF or PPT)</li><li><strong>Handing off to engineering</strong> → PRD + User Stories</li><li><strong>Preparing for QA</strong> → UAT Test Plan</li><li><strong>Announcing to customers</strong> → Customer Email or Blog Post</li><li><strong>Supporting a launch</strong> → Social Media Posts (LinkedIn, Twitter, Instagram)</li></ul><p>There&#39;s no requirement to produce all document types for every Feature — generate what&#39;s useful for where the Feature is in its lifecycle.</p><hr><h2 id="documents-per-feature" tabindex="-1">Documents per Feature <a class="header-anchor" href="#documents-per-feature" aria-label="Permalink to &quot;Documents per Feature&quot;">​</a></h2><p>Each Feature supports one Document per type — for example, one PRD, one Opportunity Canvas, one Customer Email, and so on. You cannot create two Customer Emails for the same Feature.</p><p>If you need variations of the same document type, the recommended approach is to edit and iterate within the single document rather than maintaining separate copies.</p><hr><p><em>Next: Advanced Features &amp; Customization — prompt customization, the Opportunity Canvas appendix, and tips for getting the most from AI generation.</em></p>',49)])])}const m=t(i,[["render",r]]);export{p as __pageData,m as default};
